-- Relocation Tools — Vatandaşlık Testi (Almanya) [vatandaslik_testi_almanya].
-- BAMF Einbürgerungstest soru havuzu (469 soru, 16 eyalet + Genel).
-- Kaynak: almanya101 canlı DB (vatandaslik_sorulari) — Management API ile çekilip seed'e dönüştürüldü (2026-06-30).
-- STANDALONE araç: soru havuzu + sınav simülatörü (DB skorlama/oturum motoruna girmez).
-- Sayfa gövdesi germany-standalone-tools registry'den (RelocationToolPage → VatandaslikTestiToolPage).
--
-- secenekler jsonb = {a,b,c,d}; dogru_cevap = 'a'..'d'. eyalet='Genel' → tüm modlarda ortak havuz.

create table if not exists public.germany_citizenship_questions (
  id integer primary key,
  soru_almanca text not null,
  soru_turkce text not null,
  secenekler jsonb not null,
  dogru_cevap text not null check (dogru_cevap in ('a','b','c','d')),
  eyalet text not null,
  image_url text,
  created_at timestamptz not null default now()
);

create index if not exists idx_germany_citizenship_eyalet on public.germany_citizenship_questions (eyalet);

alter table public.germany_citizenship_questions enable row level security;

-- Herkese açık okuma (login gerekmez; sorular kamuya açık BAMF havuzu).
drop policy if exists "germany_citizenship_public_read" on public.germany_citizenship_questions;
create policy "germany_citizenship_public_read"
  on public.germany_citizenship_questions for select
  to anon, authenticated
  using (true);

grant select on public.germany_citizenship_questions to anon, authenticated;

-- Idempotent seed: önce temizle, sonra yükle.
delete from public.germany_citizenship_questions;


-- ---------------------------------------------------------------------------
-- HUB KAYDI — relocation_tools satırı (kart için). Standalone araç; soru seed'i/skor RPC'si bu
-- araç için relocation_tool_questions'a GİRMEZ (kendi tablosu var). result_kind sadece CHECK için.
-- ---------------------------------------------------------------------------
   detailed_question_count, result_kind, requires_auth, is_active, sort_order, weights)
values (
  'vatandaslik_testi_almanya',
  'vatandaslik-testi-almanya',
  'Vatandaşlık Testi (Almanya)',
  'Germany Citizenship Test (Einbürgerungstest)',
  'Resmi BAMF soru havuzuyla Einbürgerungstest pratiği: 300+ genel soru, gerçek deneme sınavı (33 soru / 60 dk) ve eyalet soruları. Her soru Almanca + Türkçe.',
  'germany_tools',
  0, 0, 'score', false, true, 104,
  '{}'::jsonb
)
on conflict (key) do update set
  slug = excluded.slug, title_tr = excluded.title_tr, title_en = excluded.title_en,
  summary_tr = excluded.summary_tr, category = excluded.category,
  result_kind = excluded.result_kind, requires_auth = excluded.requires_auth,
  is_active = excluded.is_active, sort_order = excluded.sort_order, updated_at = now();
