  (342, 'Frau Seger bekommt ein Kind. Was muss sie tun, um Elterngeld zu erhalten?', 'Bayan Seger bir çocuk sahibi oluyor. Ebeveyn parası (Elterngeld) alabilmek için ne yapması gerekir?', '{"a":"Sie muss an ihre Krankenkasse schreiben.","b":"Sie muss nichts tun, denn sie bekommt automatisch Elterngeld.","c":"Sie muss einen Antrag bei der Elterngeldstelle stellen.","d":"Sie muss das Arbeitsamt um Erlaubnis bitten."}'::jsonb, 'c', 'Genel', null),
  (343, 'Wer entscheidet, ob ein Kind in Deutschland in den Kindergarten geht?', 'Almanya''da bir çocuğun anaokuluna gidip gitmeyeceğine kim karar verir?', '{"a":"der Staat","b":"die Bundesländer","c":"die Eltern / die Erziehungsberechtigten","d":"die Schulen"}'::jsonb, 'c', 'Genel', null),
  (344, 'Maik und Sybille wollen mit Freunden an ihrem deutschen Wohnort eine Demonstration auf der Straße abhalten. Was müssen sie vorher tun?', 'Maik ve Sybille arkadaşlarıyla birlikte Almanya''da yaşadıkları yerde sokakta bir gösteri düzenlemek istiyorlar. Önceden ne yapmaları gerekir?', '{"a":"Sie müssen nichts tun. Man darf in Deutschland jederzeit überall demonstrieren.","b":"Sie müssen die Demonstration anmelden.","c":"Sie können gar nichts tun, denn Demonstrationen sind in Deutschland grundsätzlich verboten.","d":"Maik und Sybille müssen einen neuen Verein gründen, weil nur Vereine demonstrieren dürfen."}'::jsonb, 'b', 'Genel', null),
  (345, 'Welchen Schulabschluss braucht man normalerweise, um an einer Universität in Deutschland ein Studium zu beginnen?', 'Almanya''da bir üniversitede eğitime başlamak için normalde hangi okul diplomasına ihtiyaç vardır?', '{"a":"das Abitur","b":"ein Diplom","c":"die Prokura","d":"eine Gesellenprüfung"}'::jsonb, 'a', 'Genel', null),
  (346, 'Wer darf in Deutschland nicht als Paar zusammenleben?', 'Almanya''da kimler çift olarak birlikte yaşayamaz?', '{"a":"Hans (20 Jahre) und Marie (19 Jahre)","b":"Tom (20 Jahre) und Klaus (45 Jahre)","c":"Sofie (35 Jahre) und Lisa (40 Jahre)","d":"Anne (13 Jahre) und Tim (25 Jahre)"}'::jsonb, 'd', 'Genel', null),
